else{$s=$conn->prepare("INSERT INTO complaints(user_id,category,title,description,location,priority,status) VALUES(?,?,?,?,?,?,'Open')");$s->bind_param("isssss",$_SESSION["user_id"],$cat,$title,$desc,$loc,$pri);
