include "../includes/header.php";?><div class="form"><h2>Submit Complaint</h2><?php if($msg):?><div class="alert bad"><?=e($msg)?></div><?php endif;?><?php if($ok):?><div class="alert ok"><?=e($ok)?></div><?php endif;?>
